/* Field guide and simulated AST report share the exact combat matching data. */
(() => {
  const M=window.NABO_MICRO,art=window.NaboToyArt.html;
  class NaboFieldGuide {
    constructor(api){this.api=api;this.all=false;document.getElementById('arsenalToggle').onclick=()=>{this.all=!this.all;this.render();};document.getElementById('codexNav').onclick=()=>this.open('pathogens');document.getElementById('scanBtn').onclick=()=>this.open('report');}
    species(){return [...new Set(this.api.level().enemies.map(e=>e.pathogen))];}
    render(){const {ammo,rank,xp}=this.api.state(),ids=this.species(),relevant=new Set(ids.flatMap(id=>id==='myco'||id==='chlamydia'?['azithro','doxy']:[M.pathogens[id].best])),list=Object.entries(M.drugs).filter(([id,d])=>this.all||relevant.has(id));
      document.getElementById('arsenalRank').textContent=`补给权限 ${rank} · ${M.rankNames[rank]}`;
      document.getElementById('arsenalToggle').textContent=this.all?'收起全部补给 ↑':'查看全部 10 种补给 ↗';
      document.getElementById('arsenalCards').innerHTML=list.map(([id,d])=>{const locked=d.rank>rank,mastery=1+Math.min(2,Math.floor((xp[id]||0)/6));return `<button class="drug-card ${ammo===id?'selected':''} ${locked?'locked':''}" data-ammo="${id}" style="--drug:${d.color}" ${locked?'disabled':''} aria-pressed="${ammo===id}" aria-label="${d.name}，${locked?'权限'+d.rank+'解锁':'熟练等级'+mastery}"><span class="supply-figure">${art('supplies',id,'',d.name)}<i class="toy-rank rank-${d.rank}">${d.rank===6?'♛':'◇'} ${d.rank}</i></span><span><small>${d.family}</small><b>${d.name}</b><em>${locked?'权限 '+d.rank+' 解锁':'熟练 Lv.'+mastery+' · '+(xp[id]||0)+' 次匹配'}</em></span>${ammo===id?'<strong>✓</strong>':''}</button>`;}).join('');
      document.querySelectorAll('button[data-ammo]').forEach(b=>b.onclick=()=>this.api.select(b.dataset.ammo,true));
      const selected=M.drugs[ammo];document.getElementById('selectedDrug').innerHTML=`${art('supplies',ammo,'selected-figure','')}<b>${selected.name}</b><span>${selected.mechanism}</span>`;
      document.getElementById('encounterList').innerHTML=ids.map(id=>{const p=M.pathogens[id],s=M.result(id,ammo);return `<button class="encounter-chip" data-species="${id}" style="--micro:${p.color}">${art('pathogens',id,'encounter-figure','')}<b>Lv.${p.tier} ${p.short}</b><span class="match-${s==='S'?'yes':s==='R'?'no':'other'}">${s==='S'?'匹配':s==='R'?'耐药':s==='—'?'不适用':'未建模'}</span></button>`;}).join('');document.querySelectorAll('[data-species]').forEach(b=>b.onclick=()=>this.open('report',b.dataset.species));
    }
    open(tab='pathogens',focus){const {rank,xp}=this.api.state(),ids=this.species();let body='';
      const tabs=`<div class="codex-tabs">${[['pathogens','病原体图鉴'],['drugs','补给档案'],['report','本关药敏']].map(([id,label])=>`<button data-codex-tab="${id}" class="${id===tab?'active':''}">${label}</button>`).join('')}</div>`;
      if(tab==='pathogens')body=`<div class="codex-grid">${Object.entries(M.pathogens).map(([id,p])=>`<article class="species-card ${ids.includes(id)?'in-stage':''}" style="--micro:${p.color}"><div class="species-title"><span class="codex-figure">${art('pathogens',id,'',p.name)}<i class="toy-rank rank-${p.tier}">${p.tier===5?'♛':'◇'} ${p.tier}</i></span><span><small>${p.gram} · 游戏威胁 Lv.${p.tier} ${ids.includes(id)?'· 本关出没':''}</small><b>${p.name}</b></span></div><em>${p.latin}</em><p>${p.trait}</p>${p.tier>=4?`<div class="armor-preview">${[['normal','完整护甲'],['damaged','护甲开裂'],['bare','核心露出']].map(([state,text])=>`<span>${art('pathogens',id,'',text,state)}<small>${text}</small></span>`).join('')}</div>`:''}<div class="species-foot"><span>${p.group}</span><button class="text-button" data-inspect="${id}">查看模拟药敏 →</button></div></article>`).join('')}</div>`;
      if(tab==='drugs')body=`<p class="codex-explainer">权限表示关卡解锁顺序，熟练 Lv.1–3 表示游戏经验；不是临床效力或“越贵越强”的排名。每种补给的匹配命中均造成 2 点游戏伤害。</p><div class="codex-grid">${Object.entries(M.drugs).map(([id,d])=>`<article class="species-card" style="--micro:${d.color}"><div class="species-title"><span class="codex-figure">${art('supplies',id,'',d.name)}<i class="toy-rank rank-${d.rank}">${d.rank===6?'♛':'◇'} ${d.rank}</i></span><span><small>权限 ${d.rank} · 熟练 Lv.${1+Math.min(2,Math.floor((xp[id]||0)/6))}</small><b>${d.name}</b></span></div><em>${d.family} · ${d.mechanism}</em><p>${d.description}</p><button class="text-button" data-equip="${id}" ${d.rank>rank?'disabled':''}>${d.rank>rank?'后续关卡解锁':'装入下一发 →'}</button></article>`).join('')}</div>`;
      if(tab==='report'){const rows=focus?[focus]:ids;body=`<div class="report-banner"><span>⌕</span><div><b>培养与药敏扫描完成</b><p>${focus?M.pathogens[focus].name+' · 图鉴示例分离株':this.api.level().title+' · '+ids.length+' 类模拟分离株'}。S 匹配 · R 耐药 · — 不适用 · ? 未建模</p></div></div><div class="report-scroll"><table class="ast-table"><thead><tr><th>模拟分离株</th>${Object.values(M.drugs).map(d=>`<th title="${d.name}">${d.short}</th>`).join('')}</tr></thead><tbody>${rows.map(id=>{const p=M.pathogens[id];return `<tr><th>${art('pathogens',id,'report-figure','')}${p.short}<small>Lv.${p.tier} · ${p.gram}</small></th>${Object.keys(M.drugs).map(drug=>{const r=M.result(id,drug);return `<td class="ast-${r==='S'?'s':r==='R'?'r':'na'}">${r}</td>`;}).join('')}</tr>`;}).join('')}</tbody></table></div><div class="report-actions">${rows.map(id=>{const p=M.pathogens[id],d=M.drugs[p.best];return `<button data-equip="${p.best}" class="report-equip" ${d.rank>rank?'disabled':''} style="--micro:${p.color}"><b>${p.short}</b><span>${d.name}</span><em>${d.rank>rank?'权限 '+d.rank+' 解锁':'装入匹配补给 →'}</em></button>`;}).join('')}</div><p class="codex-explainer">PEN 青霉素 · CFZ 头孢唑林 · CRO 头孢曲松 · IMM 幻想免疫护盾 · AZM 阿奇霉素 · DOX 多西环素 · VAN 万古霉素 · FEP 头孢吡肟 · MEM 美罗培南 · CZA 头孢他啶／阿维巴坦</p>`;}
      this.api.modal('NABO MICRO LAB',`<h2>${tab==='pathogens'?'微观世界，认识一下。':tab==='drugs'?'补给各有所长。':'选对目标，再出发。'}</h2><p class="modal-lead">革兰阳性／阴性是细菌分类。病毒另属一类，支原体与衣原体属于细菌。Lv. 是游戏威胁等级。</p>${tabs}${body}<div class="guide-note">${M.boundary}<br>实际用药还涉及感染部位、耐药机制、检测结果与患者情况。<a href="https://www.cdc.gov/mycoplasma/hcp/clinical-care/index.html" target="_blank" rel="noopener">CDC 支原体</a> · <a href="https://www.cdc.gov/cpneumoniae/hcp/clinical-overview/" target="_blank" rel="noopener">CDC 肺炎衣原体</a> · <a href="https://www.idsociety.org/practice-guideline/amr-guidance/" target="_blank" rel="noopener">IDSA 耐药菌</a></div>`);
      document.querySelectorAll('[data-codex-tab]').forEach(b=>b.onclick=()=>this.open(b.dataset.codexTab));document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>this.open('report',b.dataset.inspect));document.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{this.api.close();this.api.select(b.dataset.equip,true);});
    }
  }
  window.NaboFieldGuide=NaboFieldGuide;
})();
